**3. Implement refresh tokens:**
```java
@Service
public class TokenService {
  public TokenPair generateTokens(User user) {
    // Short-lived access token (15 min)
    String accessToken = generateAccessToken(user, Duration.ofMinutes(15));

    // Long-lived refresh token (7 days)
    String refreshToken = generateRefreshToken(user, Duration.ofDays(7));

    // Store refresh token in database
    RefreshToken rt = new RefreshToken();
    rt.setToken(refreshToken);
    rt.setUserId(user.getId());
    rt.setExpiresAt(Instant.now().plus(Duration.ofDays(7)));
    refreshTokenRepo.save(rt);

    return new TokenPair(accessToken, refreshToken);
  }

  @Transactional
  public String refreshAccessToken(String refreshToken) {
    RefreshToken rt = refreshTokenRepo.findByToken(refreshToken)
      .orElseThrow(() -> new UnauthorizedException("Invalid refresh token"));

    if (rt.isExpired() || rt.isRevoked()) {
      throw new UnauthorizedException("Refresh token expired or revoked");
    }

    User user = userRepo.findById(rt.getUserId())
      .orElseThrow();

    return generateAccessToken(user, Duration.ofMinutes(15));
  }

  public void revokeAllUserTokens(Long userId) {
    refreshTokenRepo.revokeAllForUser(userId);
  }
}
```

