@PostMapping("/auth/login")
public ResponseEntity<?> login(@RequestBody LoginRequest request) {
  User user = authenticateUser(request);

  if (user.isMfaEnabled()) {
    String tempToken = generateTempToken(user);
    return ResponseEntity.ok(new MfaRequiredResponse(tempToken));
  }

  TokenPair tokens = tokenService.generateTokens(user);
  return ResponseEntity.ok(tokens);
}

@PostMapping("/auth/verify-mfa")
public ResponseEntity<?> verifyMfa(@RequestBody MfaRequest request) {
  User user = validateTempToken(request.getTempToken());

  if (!mfaService.verifyMFA(user, request.getCode())) {
    throw new UnauthorizedException("Invalid MFA code");
  }

  TokenPair tokens = tokenService.generateTokens(user);
  return ResponseEntity.ok(tokens);
}
```

